import{describe,it,expect}from"vitest";describe("Reading progress bar calculations",()=>{it("calculates scroll progress correctly",()=>{const e=(e,t,c)=>{const r=t-c;return r<=0?0:Math.min(100,Math.max(0,e/r*100))};expect(e(0,1e3,500)).toBe(0),expect(e(250,1e3,500)).toBe(50),expect(e(500,1e3,500)).toBe(100),expect(e(600,1e3,500)).toBe(100)})});